triple[] Pp = {-P[0], -P[1], -P[2], -P[3], -P[4]};

// draw octahedron
triple pt(int k){ return (3*P[k] + P[1])/4; }
triple ptp(int k){ return (3*Pp[k] + Pp[1])/4; }
draw(pt(2)--pt(3)--pt(4)--cycle, gray(0.6));
draw(ptp(2)--pt(3)--ptp(4)--cycle, gray(0.6));
draw(ptp(2)--pt(4), gray(0.6));
